import csv, collections, re, datetime

csv_path = "/home/andrea-zabala-c/Desktop/resultado_xref_nacional_segunda_vuelta.csv"
output_html = "/home/andrea-zabala-c/Desktop/ENTREGABLES_FORENSES_E14/REPORTE_XREF_POR_DEPARTAMENTO.html"

def get_depto_from_path(path):
    m = re.search(r'claveros_pdf/([^/]+)/', path)
    return m.group(1).upper() if m else "DESCONOCIDO"

stats = collections.defaultdict(lambda: {'LIMPIO': 0, 'CORRUPTO_XREF': 0, 'CORRUPTO_TRAILER': 0, 'ADVERTENCIA': 0, 'total': 0})

with open(csv_path, 'r', errors='replace') as f:
    reader = csv.reader(f)
    next(reader)
    for row in reader:
        if not row: continue
        pdf_path = row[0].strip('"')
        estado = row[1].strip('"') if len(row) > 1 else ''
        depto = get_depto_from_path(pdf_path)
        stats[depto]['total'] += 1
        if estado in stats[depto]:
            stats[depto][estado] += 1

total_global = sum(v['total'] for v in stats.values())
corruptos_global = sum(v.get('CORRUPTO_XREF',0)+v.get('CORRUPTO_TRAILER',0) for v in stats.values())
limpios_global = sum(v.get('LIMPIO',0) for v in stats.values())
pct_global = corruptos_global/total_global*100 if total_global else 0
ahora = datetime.datetime.now().strftime("%d/%m/%Y %H:%M")

filas_html = ""
for depto in sorted(stats.keys()):
    v = stats[depto]
    total = v['total']
    limpio = v.get('LIMPIO', 0)
    corrupto = v.get('CORRUPTO_XREF', 0) + v.get('CORRUPTO_TRAILER', 0)
    adv = v.get('ADVERTENCIA', 0)
    pct = corrupto/total*100 if total else 0

    if corrupto == 0:
        row_class = "limpio"
        badge = '<span class="badge badge-ok">✔ LIMPIO</span>'
    elif pct >= 99:
        row_class = "critico"
        badge = '<span class="badge badge-critico">⚠ CRÍTICO</span>'
    else:
        row_class = "anomalo"
        badge = '<span class="badge badge-anomalo">● ANOMALÍA</span>'

    bar_w = min(int(pct), 100)
    filas_html += f"""
    <tr class="{row_class}">
      <td class="depto-name">{depto}</td>
      <td class="num">{total:,}</td>
      <td class="num green">{limpio:,}</td>
      <td class="num red">{corrupto:,}</td>
      <td class="num yellow">{adv:,}</td>
      <td class="pct-cell">
        <div class="bar-bg"><div class="bar-fill" style="width:{bar_w}%"></div></div>
        <span class="pct-label">{pct:.1f}%</span>
      </td>
      <td>{badge}</td>
    </tr>"""

